import{_ as d,o as r,c as e,ag as o}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"与上游差异","description":"","frontmatter":{"title":"与上游差异"},"headers":[],"relativePath":"zh/UncivCN/Differences.md","filePath":"zh/UncivCN/Differences.md"}'),n={name:"zh/UncivCN/Differences.md"};function a(i,t,s,c,l,h){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="uncivcn-与上游差异对照" tabindex="-1">UncivCN 与上游差异对照 <a class="header-anchor" href="#uncivcn-与上游差异对照" aria-label="Permalink to &quot;UncivCN 与上游差异对照&quot;">​</a></h1><blockquote><p>本文只记录<strong>游戏内容</strong>差异。分支的工程/代码规范见 <a href="./Coding-standards.html">代码规范</a>， 文档站维护细节亦在其中。</p></blockquote><table tabindex="0"><thead><tr><th>功能</th><th>上游 Unciv</th><th>UncivCN</th></tr></thead><tbody><tr><td>联机方式</td><td>动态回合（严格顺序制）</td><td>动态回合 + <strong>轮询联机</strong>（时间片轮转，等待上限数秒）</td></tr><tr><td>联机服务器</td><td>官方服务器</td><td>默认 <code>sp.unciv.cn:30123</code></td></tr><tr><td>联机公平性</td><td>—</td><td>随机数读档可变功能联机时禁用</td></tr><tr><td>地图类型</td><td>标准地图</td><td>+ <strong>三种镜像地图</strong>（资源对称）+ <strong>环形地图</strong>（取消半径奇偶限制）</td></tr><tr><td>模组脚本</td><td>纯 JSON</td><td>+ <strong>Lua 脚本</strong>（Unique 触发 / 生命周期钩子 / ctx API）</td></tr><tr><td>模组 JSON</td><td>整对象替换 / 基础 <code>_mergeAction</code></td><td><strong>MergeAction 字段级合并扩展</strong>、新增 Countables 参数</td></tr><tr><td>模组检查器</td><td>检查 JSON</td><td>+ 筛查 Lua 错误</td></tr><tr><td>地块归属</td><td>无</td><td><strong>tile-claim</strong>（城市宣称/交换地块）</td></tr><tr><td>人口管理</td><td>手动锁定</td><td>+ <strong>自动锁定按钮</strong>（永久切换不锁/锁人口）</td></tr><tr><td>地图标注</td><td>无</td><td><strong>单位钉 / 地图钉</strong>（备注数据存 <code>{存档名}_notes</code>）</td></tr><tr><td>开局配置</td><td>手动设置</td><td><strong>设置导出/导入剪贴板</strong></td></tr><tr><td>存档兼容</td><td>无隔离</td><td><strong>版本隔离</strong>（旧版无法加载新版存档）</td></tr><tr><td>内置模组</td><td>无</td><td>4.21.0.1 曾自带 UCCC；4.21.5.1 起撤销，不再打包任何模组</td></tr><tr><td>本地化</td><td>多语言</td><td>+ 完整中文本地化（含 Unique 翻译）</td></tr><tr><td>游戏内容</td><td>同步上游</td><td>始终跟进上游最新版本（当前基于 4.21.6）</td></tr></tbody></table><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>UncivCN 全部新功能均为<strong>增量实现</strong>，不修改上游既有行为；关闭相关选项后与上游一致</li><li>中文界面与文档为本分支的一等公民：全部 Unique、UI 字符串均有中文翻译</li><li>版本号 = 上游版本 + CN 子版本号（<code>.1</code>、<code>.2</code>、<code>.3</code>…，同一上游版本可发多个 CN 子版本，跟进新上游后从 <code>.1</code> 重新开始），可通过 <a href="./Changelog.html">更新日志</a> 追踪演进</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./Coding-standards.html">代码规范（工程/文档站/翻译）</a></li><li><a href="./Changelog.html">更新日志</a></li><li><a href="./Features.html">新特性</a></li></ul>',7)])])}const f=d(n,[["render",a]]);export{u as __pageData,f as default};
